import functools


class Registry:
    def __init__(self):
        self._handlers = {}

    def register(self, name):
        def decorator(fn):
            self._handlers[name] = fn
            return fn
        return decorator

    def dispatch(self, name, *args, **kwargs):
        if name not in self._handlers:
            raise KeyError(f"No handler for '{name}'")
        return self._handlers[name](*args, **kwargs)


def chain_predicates(*predicates):
    def combined(x):
        return all(p(x) for p in predicates)
    return combined


def once(fn):
    result = None
    called = False

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        nonlocal result, called
        if not called:
            result = fn(*args, **kwargs)
            called = True
        return result

    return wrapper
